const VH_REFERENCE_VIEWS={identity:[['turnaround','Character turnaround sheet'],['front_face','Front portrait'],['three_quarter','Three-quarter portrait'],['profile','Side profile'],['full_body','Full body']],person:[['front_face','Front portrait'],['three_quarter','Three-quarter portrait'],['profile','Side profile'],['full_body','Full body']],place:[['establishing','Room or place overview'],['reverse_angle','Opposite angle'],['detail','Detail']],zone:[['establishing','Room overview'],['reverse_angle','Opposite angle'],['detail','Detail']],prop:[['front','Product image'],['back','Back'],['detail','Detail']],garment:[['front','Front'],['back','Back'],['detail','Detail']],pose:[['front_camera_selfie','Front-camera selfie'],['mirror_selfie','Mirror selfie'],['full_body','Full-body pose']]};
function vhOptions(rows,value=''){if(value!==''&&!rows.some(([id])=>String(id)===String(value)))rows=[...rows,[value,'Current: '+value]];return rows.map(([id,label])=>`<option value="${escapeHTML(id)}" ${String(value)===String(id)?'selected':''}>${escapeHTML(label)}</option>`).join('');}
function vhOpenConnectionSettings(target='accounts'){
 if(target==='maps')return vhMapsSetup();
 showGlobalSettings();activateSettingsSection(target,{clearSearch:true,scroll:false});
}
function vhMapsSetup(){
 const existing=document.getElementById('vh-maps-setup');if(existing){existing.focus();return existing;}
 const d=vhProductDialog('Maps & places','Shared across all lives · Connect place search and journey estimates without leaving Life.');d.id='vh-maps-setup';
 const f=d.querySelector('form'),status=d.querySelector('[role=status]');
 f.innerHTML=`<section class="vh-map-summary"><span class="vh-eyebrow">Connection status</span><h3 data-summary>Reading saved setup…</h3><p data-detail>Checking the local service.</p><button type="button" data-refresh>Refresh saved setup</button></section>
 <fieldset data-settings disabled><label>Search & routing provider<select name="provider"><option value="openrouteservice">openrouteservice — walking, cycling & driving</option><option value="google">Google Maps — places & routes</option></select></label><p data-provider-help></p><label>API key <small>Leave blank to keep the saved key</small><input name="key" type="password" autocomplete="off" spellcheck="false" placeholder="Paste a key only to add or replace it"></label><a data-key-link target="_blank" rel="noopener noreferrer">Get a provider key</a><div class="vh-overview-actions"><button type="submit">Save connection</button><button type="button" data-remove>Remove selected provider’s saved key</button></div></fieldset>
 <section><h3>Test place search</h3><p>Search for a named place and city. This makes one provider request and may use provider credits. Results are a preview; this does not add destinations to her life.</p><label>Place and city<input name="query" maxlength="300" placeholder="e.g. McDonald’s, Phoenix, Arizona"></label><button type="button" data-test disabled>Test saved connection</button><div data-results></div></section>
 <details><summary>What this connection enables</summary><p>Place matching and route estimates. Automatic neighbourhood discovery is not connected yet: the current life engine chooses from saved places and routes.</p><p>There is currently one active provider. Switching providers is explicit; automatic fallback is not configured.</p><p data-usage></p></details>`;
 const group=f.querySelector('[data-settings]'),provider=f.elements.provider,key=f.elements.key,test=f.querySelector('[data-test]'),refresh=f.querySelector('[data-refresh]'),results=f.querySelector('[data-results]');let saved=null,busy=false,uncertain=false;
 const label=id=>id==='google'?'Google Maps':'openrouteservice';
 const configured=id=>!!(id==='google'?saved?.configured:saved?.orsConfigured);
 const dirty=()=>!!saved&&(provider.value!==saved.provider||!!key.value.trim());
 const sync=()=>{group.disabled=busy||!saved;refresh.disabled=busy;test.disabled=busy||!saved||uncertain||dirty()||!configured(saved?.provider);f.querySelector('[data-remove]').disabled=busy||!saved||!(provider.value==='google'?saved.source==='settings':saved.orsSource==='settings');d.setAttribute('aria-busy',String(busy));};
 const help=()=>{const google=provider.value==='google';f.querySelector('[data-provider-help]').textContent=google?'Enable Places API (New) and Routes API in your Google project. Billing is required.':'Uses a HeiGIT / openrouteservice key. Walking, cycling and driving are supported; transit retains saved estimates.';const link=f.querySelector('[data-key-link]');link.href=google?'https://developers.google.com/maps/documentation/routes/get-api-key':'https://account.heigit.org/';link.textContent=google?'Google Maps setup instructions':'Get an openrouteservice key';sync();};
 const reflect=data=>{if(!['google','openrouteservice'].includes(data.provider))throw Error('The service returned an invalid Maps configuration. Update or reconnect the local launcher.');saved=data;uncertain=false;provider.value=data.provider;f.querySelector('[data-summary]').textContent=label(data.provider)+(configured(data.provider)?' · key saved':' · key needed');f.querySelector('[data-detail]').textContent=configured(data.provider)?'Provider access has not been tested in this panel. Use Test saved connection below.':'Add a key or select a provider with a saved key.';const u=data.usage;f.querySelector('[data-usage]').textContent=u?`Horde usage today: ${u.providers?.[data.provider]?.today||0} / ${u.dailyLimit} requests for this provider. Shared across all lives; resets at midnight UTC. Provider limits also apply.`:'';help();};
 const run=async(kind,operation)=>{if(busy)return;busy=true;sync();status.textContent=kind;try{await operation();}catch(error){status.textContent=error.message;}finally{busy=false;sync();}};
 const read=()=>run('Reading saved Maps setup…',async()=>{try{const data=await mcpBridgeRequest('/maps/settings');if(!d.open)return;reflect(data);status.textContent='Saved setup loaded. No provider request was made.';}catch(error){uncertain=true;f.querySelector('[data-summary]').textContent='Saved setup unavailable';f.querySelector('[data-detail]').textContent='The connection could not be checked. Existing settings have not been changed. Retry with Refresh saved setup.';throw error;}});
 refresh.onclick=()=>{if(dirty()){status.textContent='Save your connection changes before refreshing, or close and reopen to discard them.';return;}read();};
 provider.onchange=()=>{results.replaceChildren();help();status.textContent='Provider selection is a draft. Save connection to apply it.';};key.oninput=()=>{sync();status.textContent='Key entered. Save connection to apply it.';};
 f.onsubmit=e=>{e.preventDefault();run('Saving connection…',async()=>{const id=provider.value,body={provider:id};if(key.value.trim())body[id==='google'?'googleKey':'orsKey']=key.value.trim();if(!configured(id)&&!key.value.trim())throw Error('Paste a key for this provider before saving.');try{const data=await mcpBridgeRequest('/maps/settings',{method:'POST',body});reflect(data);key.value='';results.replaceChildren();status.textContent=label(data.provider)+' connection saved. Test place search to verify access.';}catch(error){uncertain=true;throw Error(error.message+' Save was not confirmed. Your draft is retained; retry Save or reopen to check the saved setup.');}});};
 f.querySelector('[data-remove]').onclick=()=>run('Removing saved key…',async()=>{const id=provider.value;try{reflect(await mcpBridgeRequest('/maps/settings',{method:'POST',body:id==='google'?{remove:true}:{removeOrs:true}}));key.value='';results.replaceChildren();status.textContent='Saved key removed. '+(configured(id)?'A launcher environment key is still available.':'This provider needs a key before it can be used.');}catch(error){uncertain=true;throw Error(error.message+' Removal was not confirmed. Refresh to check the saved setup.');}});
 test.onclick=()=>run('Searching with '+label(saved.provider)+'…',async()=>{const query=f.elements.query.value.trim();if(!query)throw Error('Enter a place and city to test search.');results.replaceChildren();const data=await mcpBridgeRequest('/maps/search',{method:'POST',body:{provider:saved.provider,query},timeoutMs:20000});if(!d.open)return;for(const p of data.places||[]){const row=document.createElement('article');row.className='vh-entity-card';const title=document.createElement('strong'),address=document.createElement('p');title.textContent=p.displayName?.text||'Place';address.textContent=p.formattedAddress||'';row.append(title,address);results.append(row);}const credit=document.createElement('p');credit.textContent=data.attribution||label(saved.provider);results.append(credit);f.querySelector('[data-detail]').textContent='Place search verified at '+new Date().toLocaleTimeString()+'. Route access has not been tested.';status.textContent=(data.places||[]).length?`Search succeeded: ${data.places.length} results. No places were added.`:'Provider responded successfully, but found no matches. Try a more specific place and city.';});
 f.elements.query.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();if(!test.disabled)test.click();}};
 read();return d;
}
function vhTimezoneField(field){if(!field||field.dataset.smart)return;field.dataset.smart='true';const list=document.createElement('datalist');list.id='vh-zones-'+crypto.randomUUID();const zones=typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('timeZone'):['UTC'];for(const value of [...new Set(['UTC',field.value,...zones].filter(Boolean))]){const o=document.createElement('option');o.value=value;o.label=value.replaceAll('_',' ');list.append(o);}field.setAttribute('list',list.id);field.setAttribute('role','combobox');field.setAttribute('aria-autocomplete','list');field.placeholder='Search a city, e.g. London or Karachi';field.after(list);}
function vhTagField(field,suggestions=['casual','work','fitness','home','sleep','social','cozy','sporty']){
 if(!field||field.dataset.smart)return;field.dataset.smart='true';const label=field.closest('label');if(!label)return;const box=document.createElement('fieldset');box.className='vh-chip-editor';const legend=document.createElement('legend');legend.textContent=label.childNodes[0]?.textContent||'Tags';const chips=document.createElement('div'),entry=document.createElement('input'),add=document.createElement('button');entry.type='text';entry.placeholder='Add a custom tag';entry.setAttribute('aria-label','Custom '+legend.textContent);add.type='button';add.textContent='Add';const opts=document.createElement('datalist');opts.id='vh-tags-'+crypto.randomUUID();for(const tag of suggestions){const o=document.createElement('option');o.value=tag;opts.append(o);}entry.setAttribute('list',opts.id);
 const values=()=>[...new Set(field.value.split(',').map(v=>v.trim()).filter(Boolean))];const render=()=>{chips.replaceChildren();for(const tag of values()){const b=document.createElement('button');b.type='button';b.textContent=tag+' ×';b.setAttribute('aria-label','Remove '+tag);b.onclick=()=>{field.value=values().filter(v=>v!==tag).join(', ');field.dispatchEvent(new Event('input',{bubbles:true}));render();};chips.append(b);}};
 const append=()=>{const tags=entry.value.split(',').map(v=>v.trim()).filter(Boolean);field.value=[...new Set([...values(),...tags])].join(', ');entry.value='';field.dispatchEvent(new Event('input',{bubbles:true}));render();};add.onclick=append;field.form?.addEventListener('submit',()=>{if(entry.value.trim())append();},true);entry.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();append();}};field.addEventListener('input',render);box.append(legend,chips,entry,opts,add);label.hidden=true;label.after(box);render();
}
function vhSmartControls(host){
 for(const field of host.querySelectorAll('input')){const label=field.closest('label')?.textContent||field.getAttribute('aria-label')||'';if(/currency/i.test(label)&&field.type==='text'&&!field.dataset.smart){field.dataset.smart='true';const list=document.createElement('datalist');list.id='vh-currency-'+crypto.randomUUID();const names=typeof Intl.DisplayNames==='function'?new Intl.DisplayNames(undefined,{type:'currency'}):null;for(const value of typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('currency'):['USD','GBP','EUR']){const o=document.createElement('option');o.value=value;o.label=names?.of(value)||value;list.append(o);}field.setAttribute('list',list.id);field.placeholder='Search currency code';field.after(list);}else if(/timezone|IANA/i.test(label))vhTimezoneField(field);else if(field.name==='tags'||/tags/i.test(label)&&field.type==='text')vhTagField(field,/interest/i.test(label)?['music','sports','food','art','outdoors','technology','local']: /reference/i.test(label)?['front_face','three_quarter','profile','full_body','establishing','reverse_angle','detail']: /diet/i.test(label)?['vegetarian','vegan','gluten-free','dairy-free','halal','kosher']:undefined);}
 for(const field of host.querySelectorAll('select[multiple]')){if(field.dataset.smart)continue;field.dataset.smart='true';const original=field.closest('label');const box=document.createElement('fieldset');box.className='vh-choice-list';const legend=document.createElement('legend');legend.textContent=(original.childNodes[0]?.textContent||'Choose places').replace(/\(.*multiple.*\)/,'');box.append(legend);const search=document.createElement('input');search.type='search';search.placeholder='Find a place';search.setAttribute('aria-label','Search '+legend.textContent);search.oninput=()=>box.querySelectorAll('label').forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(search.value.toLowerCase()));box.append(search);for(const option of field.options){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=option.selected;check.onchange=()=>{option.selected=check.checked;field.dispatchEvent(new Event('change',{bubbles:true}));};label.append(check,document.createTextNode(option.textContent));box.append(label);}if(!field.options.length)box.append(document.createTextNode('Add a saved place first.'));original.hidden=true;original.after(box);}
}
const VH_FEED_TASKS={news:['Local news','Articles the character may notice. Get the publisher’s RSS or Atom link, not the address of an ordinary webpage.'],events:['Events','Use the organizer’s public calendar subscription (.ics) link. Dates and venues are previewed by the feed service after saving.'],transport:['Public transport','Use your transit operator’s GTFS timetable download. Load its stops, choose departure and arrival by name, then link them to saved places.'],realtime:['Transport delays','Use the operator’s GTFS-Realtime TripUpdates URL. Import its timetable first.'],flights:['Air travel','Automatically find airports from saved places using shared open data. No key required.'],sports:['Sports','Use an OpenLigaDB match-data URL for the league you follow. Other sports JSON formats are not supported.']};
