 d.querySelector('[role=status]').textContent=blocked;f.querySelector('[type=submit]').disabled=!!blocked;f.elements.interval.options[0].disabled=task!=='realtime';if(task==='realtime'&&!existing)f.elements.interval.value='1';else if(task!=='realtime'&&f.elements.interval.value==='1')f.elements.interval.value='60';
