 const routing=document.createElement('label');routing.className='vh-choice-row';const check=document.createElement('input');check.type='checkbox';check.checked=link.setupProfile?.world?.transport?.liveRouting===true;routing.append(check,document.createTextNode('Automatic live routes (uses Maps quota)'));root.querySelector('[data-connection=maps]').before(routing);const routeStatus=document.createElement('p');routeStatus.setAttribute('role','status');routeStatus.dataset.vhRouteStatus='';routeStatus.textContent=link.routingSaveMessage||'Off uses authored travel estimates. Manual Maps searches still work. Turning off stops future automatic submissions.';routing.after(routeStatus);check.onchange=async()=>{const enabled=check.checked;check.disabled=true;try{await vhUiCommand(timeline,'configure_live_routing',{enabled});link.routingSaveMessage=enabled?'Saved: eligible journeys may request a live route.':'Saved: future journeys use authored estimates without automatic Maps calls.';const visible=root.querySelector('[data-vh-route-status]');if(visible)visible.textContent=link.routingSaveMessage;}catch(error){check.checked=!enabled;routeStatus.textContent=error.message;}finally{check.disabled=false;}};
