async function vhResearchLifeDraft(companion,built,signal,progress){
 const report={checks:[["Web research",companionTextProviderId(companion)==='openrouter'?'Requested':'Unavailable',companionTextProviderId(companion)==='openrouter'?'Web search was offered to the model. Returned claims still require source review.':'This builder currently exposes web search through OpenRouter only. Life details can still be drafted.']],feeds:[],maps:[],researchNotes:Array.isArray(built.researchNotes)?built.researchNotes.slice(0,8):[]};
 const check=()=>{if(signal.aborted)throw Error('Draft cancelled.');};
 progress('Checking shared Maps configuration…');let maps;
 try{maps=await mcpBridgeRequest('/maps/settings',{timeoutMs:10000});}catch(e){report.checks.push(['Maps','Unavailable',e.message]);}check();
 const location=companion.locationLabel||'';
 if(maps && (maps.provider==='openrouteservice'?maps.orsConfigured:maps.configured)){
  for(const place of (built.places||[]).filter(p=>p.kind!=='home'&&!p.googlePlaceId&&!p.mapCoordinates).slice(0,4)){
   check();progress('Finding map choices for '+place.label+'…');
   try{const result=await mcpBridgeRequest('/maps/search',{method:'POST',body:{query:place.label+' '+location},timeoutMs:15000});check();report.maps.push({placeId:place.id,label:place.label,provider:result.provider,attribution:result.attribution,choices:(result.places||[]).slice(0,5)});}catch(e){check();report.checks.push([place.label,'Needs input',e.message]);}
  }
 }else if(maps)report.checks.push(['Maps','Needs input','Connect a shared Maps provider to resolve public places. Private homes are never automatically searched.']);
 const feeds=(Array.isArray(built.worldFeeds)?built.worldFeeds:[]).filter(x=>x&&typeof x.url==='string').slice(0,3);
 if(location&&!feeds.length)feeds.push({label:'News near '+location,url:'https://news.google.com/rss/search?'+new URLSearchParams({q:location,hl:'en-US',gl:'US',ceid:'US:en'}),tags:['local'],origin:'Location-based Google News search; English edition. Not a live-score or event-calendar feed.'});
 for(const feed of feeds){check();progress('Checking news source: '+(feed.label||'Suggested feed')+'…');try{const result=await mcpBridgeRequest('/vh2/feed-preview',{method:'POST',body:{url:feed.url},timeoutMs:15000});check();report.feeds.push({...feed,valid:true,preview:result,tags:(Array.isArray(feed.tags)?feed.tags:[]).filter(t=>typeof t==='string').slice(0,12).map(t=>t.slice(0,40))});}catch(e){check();report.feeds.push({...feed,valid:false,error:e.message});}}
 for(const [key,title] of [['places','Places'],['socialCircle','People'],['styleProfiles','Wardrobe styles'],['weeklySchedule','Commitments'],['activityOptions','Activities'],['rooms','Rooms'],['peopleLives','Independent supporting lives'],['referencePlan','Reference plan']])report.checks.push([title,built[key]?.length?'Ready to review':'Needs input',built[key]?.length?built[key].length+' proposals; not yet applied.':'No entries were generated.']);
 report.checks.push(['Images','Separate optional stage','Review the reference plan, then generate photos in Media with your chosen limit. This draft does not spend image credits.'],['World events & scores','Optional connection','Local news can be connected by this builder. Dated events and live scores require supported sources; news headlines are not a substitute.']);
 built.__setupReport=report;delete built.worldFeeds;delete built.researchNotes;return built;
}
function vhMapChoiceBinding(provider,choice){
 const point=provider==='openrouteservice'?choice?.coordinates:(choice?.location? [choice.location.longitude,choice.location.latitude]:choice?.coordinates);
 const valid=Array.isArray(point)&&point.length===2&&point.every(Number.isFinite)&&Math.abs(point[0])<=180&&Math.abs(point[1])<=90;
 return {googlePlaceId:provider==='openrouteservice'?'':String(choice?.id||''),mapCoordinates:valid?[...point]:null};
}
function vhLifeSetupReport(dialog,built){
 const report=built.__setupReport;if(!report)return;
 const section=document.createElement('section');section.className='vh-setup-help';const heading=document.createElement('h3');heading.textContent='Setup coverage';section.append(heading);
 for(const [name,state,detail] of report.checks){const p=document.createElement('p');p.textContent=name+' · '+state+' — '+detail;section.append(p);}
 for(const match of report.maps){const place=built.places.find(p=>p.id===match.placeId),original={googlePlaceId:place?.googlePlaceId||'',mapCoordinates:place?.mapCoordinates||null};const label=document.createElement('label');label.textContent='Map match: '+match.label;const select=document.createElement('select');select.innerHTML=vhOptions([['',original.googlePlaceId||original.mapCoordinates?'Keep saved location':'Leave unresolved'],...match.choices.map((p,i)=>[String(i),(p.displayName?.text||p.id)+' — '+(p.formattedAddress||'')])]);const note=document.createElement('p');note.setAttribute('role','status');note.textContent=match.attribution||'Map provider result; choose only a correct match.';select.onchange=()=>{if(!place)return;const chosen=match.choices[Number(select.value)];Object.assign(place,select.value!==''&&chosen?vhMapChoiceBinding(match.provider,chosen):original);note.textContent=select.value===''?'Saved location retained.':place.mapCoordinates?'Selected location: '+place.mapCoordinates[1]+', '+place.mapCoordinates[0]+'. The provider ID and position will be saved together.':'This result has no usable coordinates. The old pin will be cleared; add coordinates in Places to position it on the map.';};label.append(select);section.append(label,note);}
 for(const feed of report.feeds){const label=document.createElement('label');const box=document.createElement('input');box.type='checkbox';box.disabled=!feed.valid;box.checked=!!feed.valid;feed.selected=!!feed.valid;box.onchange=()=>feed.selected=box.checked;label.append(box,document.createTextNode((feed.label||'News source')+' — '+(feed.valid?'RSS checked; '+feed.preview.recentItems+' recent items':feed.error)));section.append(label);const p=document.createElement('p');p.textContent=feed.url+(feed.origin?' · '+feed.origin:'');section.append(p);}
 const sourceHeading=document.createElement('p');sourceHeading.textContent='Research claims below are model-proposed, not established character memories.';if(report.researchNotes.length)section.append(sourceHeading);
 for(const item of report.researchNotes){const p=document.createElement('p');p.textContent=String(item.claim||'').slice(0,1000)+' — '+String(item.url||'').slice(0,500);section.append(p);}
 dialog.querySelector('[data-sections]').before(section);
}
async function vhApplyDraftFeeds(timeline,built){
 const failures=[];for(const feed of built.__setupReport?.feeds||[]){if(!feed.valid||!feed.selected)continue;try{const prior=(timeline.vh2.signals?.sources||[]).find(s=>s.url===feed.url);await vhUiCommand(timeline,'configure_world_feed',{...(prior?{sourceId:prior.id}:{}),kind:'rss',purpose:'news',url:feed.url,tags:feed.tags||[],intervalMinutes:60,freshHours:48});feed.selected=false;}catch(e){failures.push((feed.label||'Feed')+': '+e.message);}}return failures;
}


