 const render=()=>{results.replaceChildren();const q=search.value.trim().toLowerCase();if(!q)return;const matches=catalogue.filter(m=>(m.id+' '+(m.name||'')).toLowerCase().includes(q));for(const model of matches.slice(0,8)){const b=document.createElement('button');b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected',String(model.id===f.elements.model.value));b.textContent=(model.name||model.id)+(model.name?' · '+model.id:'');b.style.cssText='display:block;width:100%;text-align:left;margin:4px 0;white-space:normal';b.onclick=()=>{f.elements.model.value=model.id;f.elements.custom.value='';search.value='';selected.textContent='Selected: '+model.id;results.replaceChildren();search.focus();};b.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();(e.key==='ArrowDown'?b.nextElementSibling:b.previousElementSibling)?.focus();}};results.append(b);}if(!matches.length){const p=document.createElement('p');p.textContent='No matching models. Try another name or use an exact model ID below.';results.append(p);}else if(matches.length>8){const p=document.createElement('p');p.textContent='Keep typing to narrow '+matches.length+' matches.';results.append(p);}};
 search.oninput=()=>{f.elements.model.value='';f.elements.custom.value='';selected.textContent='Choose a matching model below.';render();};search.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('button')?.focus();}if(e.key==='Enter'&&search.value.trim()){e.preventDefault();if(results.querySelectorAll('button').length===1)results.querySelector('button').click();}};
 const load=async(force=false)=>{reload.disabled=true;status.textContent='Loading models automatically…';try{catalogue=rankCompanionTextModels(await getCompanionOutputModels('text',force,provider));if(!d.open)return;render();status.textContent=catalogue.length?'Type a name to search '+catalogue.length+' models.':'No models returned. Use an exact model ID or check the provider connection.';reload.hidden=!!catalogue.length;}catch(error){if(d.open){status.textContent='Could not load models: '+error.message;reload.hidden=false;}}finally{reload.disabled=false;}};reload.onclick=()=>load(true);void load();queueMicrotask(()=>search.focus());
