 for(const [key,value] of Object.entries(draft.voice)){const p=document.createElement('p');p.textContent=key+': '+(key==='cadence'?(value<1?'Checks more often':value>1?'Checks less often':'Balanced'):value);rest.querySelector('[data-voice-review]').append(p);}
