 f.addEventListener('input',()=>{const button=f.querySelector('[type=submit]');if(button.textContent==='Applied'){button.disabled=false;button.textContent='Apply selected style';d.querySelector(':scope > [role=status]').textContent='Unsaved style changes.';}});
